await new Promise(r=>srv.listen(0,r));
const port = srv.address().port;
const fetched = await fetch('http://localhost:'+port);
console.log('fetch res:', {url:fetched.url, type:fetched.type, redirected:fetched.redirected, status:fetched.status, statusText:fetched.statusText, cookies:fetched.headers.getSetCookie()});
const c = new Context(new Request('http://localhost/'));
c.res = fetched;
console.log('after setter:', {url:c.res.url, type:c.res.type, redirected:c.res.redirected, status:c.res.status, statusText:c.res.statusText, cookies:c.res.headers.getSetCookie(), loc:c.res.headers.get('location')});
console.log('body:', await c.res.text());
srv.close();
// locked/used body behavior
const c2 = new Context(new Request('http://localhost/'));
const r1 = new Response('x'); await r1.text();
console.log('bodyUsed before:', r1.bodyUsed);
try { c2.res = r1; console.log('assign disturbed body ok, bodyUsed:', c2.res.bodyUsed); } catch(e){ console.log('assign disturbed body threw:', e.constructor.name, e.message); }
// stream body ownership
const c3 = new Context(new Request('http://localhost/'));
const src = new Response(new ReadableStream({start(ctrl){ctrl.enqueue(new TextEncoder().encode('streamed'));ctrl.close()}}));
c3.res = src;
console.log('src locked after assign:', src.body?.locked, 'dest body:', await c3.res.text());
"

